# Regenerates src/entities.rs in packed form from src/entities_original.rs.
#
# QuickGlass patch. Upstream stores the table as [(&[u8], &str); 2125]: two fat
# pointers per entry, 32 bytes each, ~66 KB of index alone. This writes the same
# names and values as two concatenated strings plus u16 end offsets (~8.5 KB of
# index). Lookup is still a binary search over the same byte-ordered names.
#
# Run from vendor/pulldown-cmark:  powershell -File mk_entities_packed.ps1

$ErrorActionPreference = 'Stop'
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
$src = Get-Content (Join-Path $here 'src\entities_original.rs') -Raw
$pairs = [regex]::Matches($src, '\(b"([^"\\]*)",\s*"((?:[^"\\]|\\.)*)"\)')
if ($pairs.Count -ne 2125) { throw "expected 2125 entities, found $($pairs.Count)" }

$header = ($src -split "`n" | Select-Object -First 20) -join "`n"   # upstream MIT notice
$names = New-Object Text.StringBuilder
$values = New-Object Text.StringBuilder
$nameEnds = @(); $valueEnds = @()
$nameLen = 0; $valueLen = 0
foreach ($p in $pairs) {
    $name = $p.Groups[1].Value
    $escapes = $p.Groups[2].Value
    [void]$names.Append($name); $nameLen += $name.Length
    [void]$values.Append($escapes)
    # UTF-8 length of the value, decoded from its \u{XXXX} escapes.
    foreach ($m in [regex]::Matches($escapes, '\\u\{([0-9A-Fa-f]+)\}')) {
        $cp = [Convert]::ToInt32($m.Groups[1].Value, 16)
        $valueLen += $(if ($cp -lt 0x80) { 1 } elseif ($cp -lt 0x800) { 2 } elseif ($cp -lt 0x10000) { 3 } else { 4 })
    }
    if ($nameLen -gt 65535 -or $valueLen -gt 65535) { throw 'offsets no longer fit in u16' }
    $nameEnds += $nameLen; $valueEnds += $valueLen
}

function Wrap([string[]]$items, [int]$perLine) {
    $lines = for ($i = 0; $i -lt $items.Count; $i += $perLine) {
        '    ' + (($items[$i..([math]::Min($i + $perLine, $items.Count) - 1)]) -join ', ') + ','
    }
    $lines -join "`n"
}
function Chunk([string]$s, [int]$width) {
    $parts = for ($i = 0; $i -lt $s.Length; $i += $width) { $s.Substring($i, [math]::Min($width, $s.Length - $i)) }
    ($parts | ForEach-Object { "    $_\" } ) -join "`n"
}
# Wraps whole tokens (escape sequences) so none is split across a line break.
function ChunkTokens([string[]]$tokens, [int]$width) {
    $lines = New-Object Collections.Generic.List[string]; $line = ''
    foreach ($t in $tokens) {
        if ($line.Length + $t.Length -gt $width -and $line.Length -gt 0) { $lines.Add("    $line\"); $line = '' }
        $line += $t
    }
    if ($line.Length -gt 0) { $lines.Add("    $line\") }
    $lines -join "`n"
}

$n = $pairs.Count
$out = @"
$header

//! Expansions of HTML5 entities

// Generated by mk_entities_packed.ps1 from entities_original.rs (upstream's
// table, generated by mk_entities.py). QuickGlass patch: same data, packed.
//
// Entry i's name is NAMES[NAME_ENDS[i-1]..NAME_ENDS[i]] (start 0 for i = 0),
// and its expansion is VALUES[VALUE_ENDS[i-1]..VALUE_ENDS[i]]. Names are in
// byte order, so lookup is a binary search.

const COUNT: usize = $n;

const NAMES: &[u8] = b"\
$(Chunk $names.ToString() 96)
";

const VALUES: &str = "\
$(ChunkTokens ([regex]::Matches($values.ToString(), '\\u\{[0-9A-Fa-f]+\}') | ForEach-Object { $_.Value }) 96)
";

const NAME_ENDS: [u16; COUNT] = [
$(Wrap ([string[]]$nameEnds) 16)
];

const VALUE_ENDS: [u16; COUNT] = [
$(Wrap ([string[]]$valueEnds) 16)
];

/// Name of entry ``index``.
fn name(index: usize) -> &'static [u8] {
    let start = if index == 0 { 0 } else { NAME_ENDS[index - 1] as usize };
    &NAMES[start..NAME_ENDS[index] as usize]
}

/// Expansion of entry ``index``.
fn value(index: usize) -> &'static str {
    let start = if index == 0 { 0 } else { VALUE_ENDS[index - 1] as usize };
    &VALUES[start..VALUE_ENDS[index] as usize]
}

pub(crate) fn get_entity(bytes: &[u8]) -> Option<&'static str> {
    let (mut low, mut high) = (0, COUNT);
    while low < high {
        let mid = (low + high) / 2;
        match name(mid).cmp(bytes) {
            core::cmp::Ordering::Less => low = mid + 1,
            core::cmp::Ordering::Greater => high = mid,
            core::cmp::Ordering::Equal => return Some(value(mid)),
        }
    }
    None
}

#[cfg(test)]
mod tests {
    // Inline module in src/entities.rs: paths resolve from src/entities/tests/.
    #[path = "../../entities_original.rs"]
    #[allow(dead_code)]
    mod original;

    /// Every upstream entity resolves identically, and near-miss names do not.
    #[test]
    fn packed_table_matches_upstream() {
        let mut checked = 0;
        for name in original::names() {
            assert_eq!(super::get_entity(name), original::get_entity(name), "entity {:?}", core::str::from_utf8(name));
            let mut longer = name.to_vec();
            longer.push(b'x');
            assert_eq!(super::get_entity(&longer), original::get_entity(&longer));
            assert_eq!(super::get_entity(&name[..name.len() - 1]), original::get_entity(&name[..name.len() - 1]));
            checked += 1;
        }
        assert_eq!(checked, super::COUNT);
        assert_eq!(super::get_entity(b""), None);
        assert_eq!(super::get_entity(b"notanentity"), None);
    }
}
"@
[IO.File]::WriteAllText((Join-Path $here 'src\entities.rs'), ($out -replace "`r`n", "`n"), (New-Object Text.UTF8Encoding($false)))
"wrote src\entities.rs: $n entries, names=$nameLen bytes, values=$valueLen bytes, index=$($n * 4) bytes"
